INSERT INTO profils (id, code, libelle, description, niveau, actif, created_at, updated_at) SELECT gen_random_uuid(), 'VALIDATEUR_NIVEAU_1', 'Validateur Niveau 1', 'Valide les conflits de niveau 1', 1, true, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM profils WHERE code = 'VALIDATEUR_NIVEAU_1');
